import {crc32} from './zip.js';
export const SOURCE_LIMIT=256*1024*1024;
export const sourceText=b=>new TextDecoder().decode(b);
export const sourceBytes=s=>new TextEncoder().encode(s);
export function sourcePath(p){if(typeof p!=='string'||p.length>512||p.includes('\\')||p.includes('\0')||p.startsWith('/')||/^[a-z]:/i.test(p)||p.split('/').some(x=>!x||x==='..'||x==='.'))throw Error('Unsafe source path.');return p;}
export function keepSource(p){return !p.split('/').some(x=>['.git','node_modules','build','__pycache__'].includes(x))&&!/\.(gba|sav|elf|o|apk|jks|keystore|p12|pyc)$/i.test(p);}
export function normalizeSource(entries){if(!(entries instanceof Map)||!entries.size||entries.size>40000)throw Error('Use a source project with 1–40,000 files.');for(const[p,b]of entries){sourcePath(p);if(!(b instanceof Uint8Array))throw Error('Invalid source bytes.');}const first=[...entries.keys()][0].split('/')[0],root=[...entries.keys()].every(p=>p.startsWith(first+'/'))?first+'/':'';let total=0;const out=new Map();for(const[p,b]of entries){const path=p.slice(root.length);if(!keepSource(path))continue;if(b.length>32*1024*1024||(total+=b.length)>SOURCE_LIMIT)throw Error('Keep source below 256 MB unpacked, with files below 32 MB.');out.set(path,b);}if(!out.size)throw Error('No editable source files found.');return out;}
async function inflate(bytes,size){if(typeof DecompressionStream==='undefined')throw Error('ZIP decompression is unavailable. Use Import folder.');const reader=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw')).getReader(),parts=[];let total=0;try{for(;;){const{value,done}=await reader.read();if(done)break;total+=value.length;if(total>size)throw Error('ZIP entry exceeds declared size.');parts.push(value);}}finally{await reader.cancel();}const out=new Uint8Array(total);let at=0;for(const p of parts){out.set(p,at);at+=p.length;}return out;}
export async function readSourceZip(input,{inflate:unpack=inflate,progress=()=>{}}={}){const b=input instanceof Uint8Array?input:new Uint8Array(input);if(b.length>SOURCE_LIMIT||b.length<22)throw Error('Choose a source ZIP below 256 MB.');const v=new DataView(b.buffer,b.byteOffset,b.byteLength);let end=-1;for(let p=b.length-22;p>=Math.max(0,b.length-65557);p--)if(v.getUint32(p,true)===0x06054b50&&p+22+v.getUint16(p+20,true)===b.length){end=p;break;}if(end<0)throw Error('Incomplete ZIP archive.');const count=v.getUint16(end+10,true),offset=v.getUint32(end+16,true);if(v.getUint16(end+4,true)||v.getUint16(end+6,true)||count===65535||count>40000||offset+v.getUint32(end+12,true)!==end)throw Error('Use a single-volume ZIP without ZIP64.');let at=offset,total=0;const entries=new Map(),seen=new Set();for(let i=0;i<count;i++){if(at+46>end||v.getUint32(at,true)!==0x02014b50)throw Error('Invalid ZIP directory.');const flags=v.getUint16(at+8,true),method=v.getUint16(at+10,true),crc=v.getUint32(at+16,true),packed=v.getUint32(at+20,true),size=v.getUint32(at+24,true),n=v.getUint16(at+28,true),extra=v.getUint16(at+30,true),comment=v.getUint16(at+32,true),local=v.getUint32(at+42,true),mode=v.getUint32(at+38,true)>>>16;if(at+46+n+extra+comment>end)throw Error('Truncated ZIP directory.');const raw=sourceText(b.subarray(at+46,at+46+n)),directory=raw.endsWith('/'),name=sourcePath(directory?raw.slice(0,-1):raw);at+=46+n+extra+comment;if(seen.has(name))throw Error('Duplicate ZIP path.');seen.add(name);if((mode&0xf000)===0xa000)throw Error('Source ZIPs cannot contain symbolic links.');if(directory||!keepSource(name))continue;if(flags&1||![0,8].includes(method))throw Error('Use an unencrypted stored or deflated ZIP.');if(size>32*1024*1024||(total+=size)>SOURCE_LIMIT)throw Error('Unpacked source exceeds 256 MB.');if(local+30>offset||v.getUint32(local,true)!==0x04034b50)throw Error('Missing ZIP header.');const dataAt=local+30+v.getUint16(local+26,true)+v.getUint16(local+28,true);if(sourceText(b.subarray(local+30,local+30+v.getUint16(local+26,true)))!==raw||v.getUint16(local+8,true)!==method||dataAt+packed>offset)throw Error('ZIP header mismatch.');const bytes=method===0?b.slice(dataAt,dataAt+packed):await unpack(b.subarray(dataAt,dataAt+packed),size);if(bytes.length!==size||crc32(bytes)!==crc)throw Error('Corrupt ZIP entry: '+name);entries.set(name,bytes);if(i%40===0){progress('Reading source '+(i+1)+' / '+count);await new Promise(r=>setTimeout(r,0));}}if(at!==end)throw Error('Invalid ZIP directory size.');return normalizeSource(entries);}
export async function readSourceFolder(files,{progress=()=>{}}={}){if(files.length>40000)throw Error('Use at most 40,000 source files.');const entries=new Map();let total=0;for(const f of files){const path=sourcePath(f.webkitRelativePath||f.name);if(!keepSource(path))continue;if(f.size>32*1024*1024||(total+=f.size)>SOURCE_LIMIT)throw Error('Source exceeds 256 MB.');if(entries.has(path))throw Error('Duplicate source path.');entries.set(path,new Uint8Array(await f.arrayBuffer()));if(entries.size%40===0)progress('Reading source '+entries.size);}return normalizeSource(entries);}
